<script setup lang="ts">import{onBeforeUnmount,onMounted,ref,watch}from'vue';import L from'leaflet';const props=defineProps<{captured?:{latitude:number;longitude:number};master?:{latitude:number;longitude:number}}>();const el=ref<HTMLElement>();let map:L.Map|undefined;function draw(){if(!map)return;map.eachLayer(x=>{if(x instanceof L.Marker||x instanceof L.CircleMarker)map!.removeLayer(x)});const points:L.LatLngExpression[]=[];if(props.master){const p:L.LatLngExpression=[props.master.latitude,props.master.longitude];L.circleMarker(p,{radius:8,color:'#1765e8',fillOpacity:.8}).addTo(map).bindPopup('Coordenada maestra');points.push(p)}if(props.captured){const p:L.LatLngExpression=[props.captured.latitude,props.captured.longitude];L.circleMarker(p,{radius:8,color:'#12a158',fillOpacity:.8}).addTo(map).bindPopup('Coordenada capturada');points.push(p)}if(points.length===1)map.setView(points[0]!,16);else if(points.length>1)map.fitBounds(L.latLngBounds(points),{padding:[35,35]})}onMounted(()=>{map=L.map(el.value!,{zoomControl:true}).setView([22,-102],6);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);draw()});watch(()=>[props.captured,props.master],draw,{deep:true});onBeforeUnmount(()=>map?.remove())</script><template><div ref="el" class="map" aria-label="Mapa de ubicación de la revisión"/></template><style scoped>.map{height:330px;border-radius:8px;overflow:hidden}</style>

